describe("DeepSeek config", () => {
  const noHome = "/nonexistent-home";

  it("auto-detects DeepSeek from ANTHROPIC_BASE_URL containing 'deepseek'", () => {
    const cfg = resolveConfig(
      {
        ANTHROPIC_API_KEY: "sk-test",
        ANTHROPIC_BASE_URL: "https://api.deepseek.com/anthropic",
        ANTHROPIC_MODEL: "claude-sonnet-4-5",
      },
      {},
      noHome,
    );
    expect(cfg.provider).toBe("deepseek");
    expect(cfg.baseUrl).toBe("https://api.deepseek.com/anthropic");
    expect(cfg.model).toBe("claude-sonnet-4-5");
    expect(cfg.apiKey).toBe("sk-test");
  });

  it("sets DeepSeek via explicit STACKPILOT_PROVIDER env var", () => {
    const cfg = resolveConfig(
      {
        ANTHROPIC_API_KEY: "sk-test",
        ANTHROPIC_BASE_URL: "https://custom-proxy.example.com",
        STACKPILOT_PROVIDER: "deepseek",
        STACKPILOT_MODEL: "deepseek-v4-pro",
      },
      {},
      noHome,
    );
    expect(cfg.provider).toBe("deepseek");
    expect(cfg.baseUrl).toBe("https://custom-proxy.example.com");
    expect(cfg.model).toBe("deepseek-v4-pro");
  });

  it("explicit STACKPILOT_PROVIDER=anthropic overrides auto-detection", () => {
    const cfg = resolveConfig(
      {
        ANTHROPIC_API_KEY: "sk-test",
        ANTHROPIC_BASE_URL: "https://api.deepseek.com/anthropic",
        STACKPILOT_PROVIDER: "anthropic",
      },
      {},
      noHome,
    );
    expect(cfg.provider).toBe("anthropic");
  });

  it("Bedrock switch overrides DeepSeek auto-detection", () => {
    const cfg = resolveConfig(
      {
        CLAUDE_CODE_USE_BEDROCK: "1",
        ANTHROPIC_BASE_URL: "https://api.deepseek.com/anthropic",
        AWS_REGION: "us-east-1",
        ANTHROPIC_DEFAULT_HAIKU_MODEL: "us.anthropic.claude-haiku-4-5-v1:0",
